
`cd /home/claude/digiweb cat > supabase/schema.sql <<'EOF' -- ========================================================= -- DigiWeb (دیجی وب) — Supabase Schema -- Run this in Supabase SQL editor (Project -> SQL Editor -> New query) -- =========================================================  -- 1) EXTENSIONS create extension if not exists "uuid-ossp";  -- 2) ENUM TYPES do $$ begin   create type user_role as enum ('user', 'admin'); exception when duplicate_object then null; end $$;  do $$ begin   create type project_status as enum (     'registered', 'pending_review', 'in_review', 'pending_payment',     'paid', 'in_progress', 'first_draft_sent', 'revisions',     'completed', 'delivered'   ); exception when duplicate_object then null; end $$;  do $$ begin   create type payment_status as enum ('unpaid', 'pending', 'paid', 'rejected'); exception when duplicate_object then null; end $$;  do $$ begin   create type receipt_status as enum ('pending', 'approved', 'rejected'); exception when duplicate_object then null; end $$;  do $$ begin   create type ticket_status as enum ('open', 'answered', 'closed'); exception when duplicate_object then null; end $$;  -- 3) PROFILES (extends auth.users) create table if not exists public.profiles (   id uuid primary key references auth.users(id) on delete cascade,   full_name text not null,   username text unique not null,   phone text,   role user_role not null default 'user',   avatar_url text,   created_at timestamptz not null default now() );  alter table public.profiles enable row level security;  create policy "profiles_select_own_or_admin"   on public.profiles for select   using (auth.uid() = id or exists (     select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin'   ));  create policy "profiles_update_own"   on public.profiles for update   using (auth.uid() = id);  create policy "profiles_insert_own"   on public.profiles for insert   with check (auth.uid() = id);  -- 4) PLANS (پلن‌ها/تعرفه‌ها) create table if not exists public.plans (   id uuid primary key default uuid_generate_v4(),   title text not null,   price_from bigint not null default 0,   delivery_days int not null default 7,   pages_count text not null default '5',   support_text text not null default '۱ ماه پشتیبانی رایگان',   features text[] not null default '{}',   is_featured boolean not null default false,   sort_order int not null default 0,   created_at timestamptz not null default now() );  alter table public.plans enable row level security; create policy "plans_public_read" on public.plans for select using (true); create policy "plans_admin_write" on public.plans for all using (   exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin') ) with check (   exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin') );  -- 5) PORTFOLIO (نمونه‌کارها) create table if not exists public.portfolio (   id uuid primary key default uuid_generate_v4(),   title text not null,   category text not null,   description text not null default '',   image_url text,   project_url text,   sort_order int not null default 0,   created_at timestamptz not null default now() );  alter table public.portfolio enable row level security; create policy "portfolio_public_read" on public.portfolio for select using (true); create policy "portfolio_admin_write" on public.portfolio for all using (   exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin') ) with check (   exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin') );  -- 6) PROJECTS (پروژه‌ها) create table if not exists public.projects (   id uuid primary key default uuid_generate_v4(),   order_number text unique not null,   user_id uuid not null references public.profiles(id) on delete cascade,   title text not null,   site_type text not null,   plan_id uuid references public.plans(id),   business_name text,   description text not null,   required_features text,   reference_sites text,   color_preference text,   budget text,   expected_time text,   price bigint,   status project_status not null default 'pending_review',   payment_status payment_status not null default 'unpaid',   admin_note text,   created_at timestamptz not null default now(),   updated_at timestamptz not null default now() );  alter table public.projects enable row level security;  create policy "projects_select_own_or_admin"   on public.projects for select   using (auth.uid() = user_id or exists (     select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin'   ));  create policy "projects_insert_own"   on public.projects for insert   with check (auth.uid() = user_id);  create policy "projects_update_own_or_admin"   on public.projects for update   using (auth.uid() = user_id or exists (     select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin'   ));  -- auto generate order number: DW-YYYY-XXXX create sequence if not exists public.project_seq start 1000;  create or replace function public.set_order_number() returns trigger as $$ begin   if new.order_number is null or new.order_number = '' then     new.order_number := 'DW-' || extract(year from now())::text || '-' || nextval('public.project_seq')::text;   end if;   new.updated_at := now();   return new; end; $$ language plpgsql;  drop trigger if exists trg_set_order_number on public.projects; create trigger trg_set_order_number   before insert on public.projects   for each row execute function public.set_order_number();  drop trigger if exists trg_touch_updated_at on public.projects; create trigger trg_touch_updated_at   before update on public.projects   for each row execute function public.set_order_number();  -- 7) PROJECT FILES (فایل‌های ضمیمه پروژه) create table if not exists public.project_files (   id uuid primary key default uuid_generate_v4(),   project_id uuid not null references public.projects(id) on delete cascade,   uploaded_by uuid not null references public.profiles(id),   file_url text not null,   file_name text not null,   created_at timestamptz not null default now() );  alter table public.project_files enable row level security; create policy "project_files_rw"   on public.project_files for all   using (     exists (select 1 from public.projects pr where pr.id = project_id and pr.user_id = auth.uid())     or exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin')   )   with check (     exists (select 1 from public.projects pr where pr.id = project_id and pr.user_id = auth.uid())     or exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin')   );  -- 8) PAYMENTS (پرداخت‌ها — مبلغ تعیین شده توسط مدیر) create table if not exists public.payments (   id uuid primary key default uuid_generate_v4(),   project_id uuid not null references public.projects(id) on delete cascade,   user_id uuid not null references public.profiles(id),   amount bigint not null,   description text,   status payment_status not null default 'pending',   created_at timestamptz not null default now() );  alter table public.payments enable row level security; create policy "payments_select_own_or_admin"   on public.payments for select   using (auth.uid() = user_id or exists (     select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin'   )); create policy "payments_admin_write"   on public.payments for insert   with check (exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin')); create policy "payments_update_own_or_admin"   on public.payments for update   using (auth.uid() = user_id or exists (     select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin'   ));  -- 9) PAYMENT RECEIPTS (رسیدهای پرداخت آپلود شده توسط کاربر) create table if not exists public.payment_receipts (   id uuid primary key default uuid_generate_v4(),   project_id uuid not null references public.projects(id) on delete cascade,   user_id uuid not null references public.profiles(id),   amount bigint not null,   paid_at date not null default now(),   tracking_code text,   description text,   image_url text not null,   status receipt_status not null default 'pending',   reject_reason text,   created_at timestamptz not null default now() );  alter table public.payment_receipts enable row level security; create policy "receipts_select_own_or_admin"   on public.payment_receipts for select   using (auth.uid() = user_id or exists (     select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin'   )); create policy "receipts_insert_own"   on public.payment_receipts for insert   with check (auth.uid() = user_id); create policy "receipts_update_own_or_admin"   on public.payment_receipts for update   using (auth.uid() = user_id or exists (     select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin'   ));  -- 10) NOTIFICATIONS (اعلان‌ها) create table if not exists public.notifications (   id uuid primary key default uuid_generate_v4(),   user_id uuid not null references public.profiles(id) on delete cascade,   title text not null,   body text not null default '',   link text,   is_read boolean not null default false,   created_at timestamptz not null default now() );  alter table public.notifications enable row level security; create policy "notifications_select_own"   on public.notifications for select using (auth.uid() = user_id); create policy "notifications_update_own"   on public.notifications for update using (auth.uid() = user_id); create policy "notifications_insert_any_authenticated"   on public.notifications for insert with check (true);  -- 11) TICKETS (تیکت‌های پشتیبانی) create table if not exists public.tickets (   id uuid primary key default uuid_generate_v4(),   user_id uuid not null references public.profiles(id) on delete cascade,   project_id uuid references public.projects(id),   subject text not null,   status ticket_status not null default 'open',   created_at timestamptz not null default now() );  alter table public.tickets enable row level security; create policy "tickets_select_own_or_admin"   on public.tickets for select   using (auth.uid() = user_id or exists (     select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin'   )); create policy "tickets_insert_own"   on public.tickets for insert with check (auth.uid() = user_id); create policy "tickets_update_own_or_admin"   on public.tickets for update   using (auth.uid() = user_id or exists (     select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin'   ));  create table if not exists public.ticket_messages (   id uuid primary key default uuid_generate_v4(),   ticket_id uuid not null references public.tickets(id) on delete cascade,   sender_id uuid not null references public.profiles(id),   message text not null,   created_at timestamptz not null default now() );  alter table public.ticket_messages enable row level security; create policy "ticket_messages_rw"   on public.ticket_messages for all   using (     exists (select 1 from public.tickets t where t.id = ticket_id and t.user_id = auth.uid())     or exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin')   )   with check (     exists (select 1 from public.tickets t where t.id = ticket_id and t.user_id = auth.uid())     or exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin')   );  -- 12) CONTACT MESSAGES (فرم تماس با ما - عمومی) create table if not exists public.contact_messages (   id uuid primary key default uuid_generate_v4(),   name text not null,   email text not null,   subject text,   message text not null,   created_at timestamptz not null default now() );  alter table public.contact_messages enable row level security; create policy "contact_insert_public"   on public.contact_messages for insert with check (true); create policy "contact_select_admin"   on public.contact_messages for select using (     exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin')   );  -- 13) SITE STATS (آمار سایت برای صفحه اصلی) create table if not exists public.site_stats (   id int primary key default 1,   projects_done int not null default 120,   happy_clients int not null default 95,   years_experience int not null default 5,   support_text text not null default '۲۴/۷' ); insert into public.site_stats (id) values (1) on conflict (id) do nothing;  alter table public.site_stats enable row level security; create policy "stats_public_read" on public.site_stats for select using (true); create policy "stats_admin_write" on public.site_stats for update using (   exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin') );  -- ========================================================= -- STORAGE BUCKETS -- Run separately or via Dashboard -> Storage -> New bucket -- ========================================================= insert into storage.buckets (id, name, public) values ('receipts', 'receipts', false) on conflict (id) do nothing;  insert into storage.buckets (id, name, public) values ('project-files', 'project-files', false) on conflict (id) do nothing;  insert into storage.buckets (id, name, public) values ('portfolio', 'portfolio', true) on conflict (id) do nothing;  insert into storage.buckets (id, name, public) values ('avatars', 'avatars', true) on conflict (id) do nothing;  -- Storage policies: receipts (private — owner + admin) create policy "receipts_storage_insert_own"   on storage.objects for insert   with check (bucket_id = 'receipts' and auth.uid()::text = (storage.foldername(name))[1]);  create policy "receipts_storage_select_own_or_admin"   on storage.objects for select   using (     bucket_id = 'receipts' and (       auth.uid()::text = (storage.foldername(name))[1]       or exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin')     )   );  -- Storage policies: project-files (private — owner + admin) create policy "project_files_storage_insert_own"   on storage.objects for insert   with check (bucket_id = 'project-files' and auth.uid()::text = (storage.foldername(name))[1]);  create policy "project_files_storage_select_own_or_admin"   on storage.objects for select   using (     bucket_id = 'project-files' and (       auth.uid()::text = (storage.foldername(name))[1]       or exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin')     )   );  -- Storage policies: portfolio (public read, admin write) create policy "portfolio_storage_public_read"   on storage.objects for select using (bucket_id = 'portfolio'); create policy "portfolio_storage_admin_write"   on storage.objects for insert with check (     bucket_id = 'portfolio' and exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin')   );  -- Storage policies: avatars (public read, owner write) create policy "avatars_storage_public_read"   on storage.objects for select using (bucket_id = 'avatars'); create policy "avatars_storage_owner_write"   on storage.objects for insert with check (     bucket_id = 'avatars' and auth.uid()::text = (storage.foldername(name))[1]   );  -- ========================================================= -- SEED DATA (optional — sample plans & portfolio so the site -- doesn't look empty on first run) -- ========================================================= insert into public.plans (title, price_from, delivery_days, pages_count, support_text, features, is_featured, sort_order) values   ('پلن پایه', 3500000, 5, '۱ تا ۳ صفحه', '۱ هفته پشتیبانی', array['طراحی Responsive','۱ صفحه اصلی + ۲ زیرصفحه','فرم تماس با ما','تحویل سریع'], false, 1),   ('پلن حرفه‌ای', 7500000, 10, '۵ تا ۸ صفحه', '۱ ماه پشتیبانی رایگان', array['طراحی اختصاصی','بهینه‌سازی سئو پایه','پنل مدیریت محتوا','۳ مرحله اصلاح رایگان'], true, 2),   ('پلن ویژه', 15000000, 18, 'نامحدود', '۳ ماه پشتیبانی رایگان', array['طراحی کاملاً اختصاصی','فروشگاه اینترنتی','درگاه پرداخت','سئو پیشرفته + آموزش'], false, 3),   ('پلن اختصاصی', 0, 30, 'برحسب نیاز', 'پشتیبانی قراردادی', array['مشاوره اختصاصی','معماری نرم‌افزار سفارشی','یکپارچه‌سازی با سامانه‌ها','SLA اختصاصی'], false, 4) on conflict do nothing;  insert into public.portfolio (title, category, description, sort_order) values   ('فروشگاه اینترنتی نوین', 'فروشگاهی', 'طراحی فروشگاه آنلاین با پنل مدیریت سفارشات و درگاه پرداخت.', 1),   ('سایت شرکتی آریا', 'شرکتی', 'وب‌سایت معرفی خدمات با طراحی مدرن و مدیریت محتوا.', 2),   ('لندینگ پیج استارتاپ فناوری', 'لندینگ پیج', 'صفحه فرود با نرخ تبدیل بالا برای کمپین تبلیغاتی.', 3),   ('سایت پرتفولیوی شخصی', 'شخصی', 'نمونه‌کار حرفه‌ای برای معرفی مهارت‌ها و پروژه‌ها.', 4) on conflict do nothing; EOF wc -l supabase/schema.sql`

